describe('HTTP Status Code Reporting', () => {
  beforeEach(() => {
    cy.visit('/status_codes');
  });

  it('should navigate to and display correct status code page content', () => {
    // Verify initial page is loaded
    cy.get('[data-testid="page-footer"]').should('contain', 'Status Codes');

    // Click the link for status code 200
    cy.get('[data-testid="200"]').click();

    // Verify navigation to correct URL
    cy.url().should('include', '/status_codes/200');

    // Verify page body contains expected text
    cy.get('[data-testid="content"]').should('contain', 'This page returned a 200 status code');

    // Verify navigation back to /status_codes
    cy.visit('/status_codes');

    // Verify page is back to initial state
    cy.get('[data-testid="page-footer"]').should('contain', 'Status Codes');
  });

  it('should handle 404 status code and display appropriate message', () => {
    // Verify initial page is loaded
    cy.get('[data-testid="page-footer"]').should('contain', 'Status Codes');

    // Click the link for status code 404
    cy.get('[data-testid="404"]').click();

    // Verify navigation to correct URL
    cy.url().should('include', '/status_codes/404');

    // Verify page body contains expected text
    cy.get('[data-testid="content"]').should('contain', 'This page returned a 404 status code');

    // Verify navigation back to /status_codes
    cy.visit('/status_codes');

    // Verify page is back to initial state
    cy.get('[data-testid="page-footer"]').should('contain', 'Status Codes');
  });
});
